export const INDIA_STATES = Object.keys(INDIA_DISTRICTS_BY_STATE)
  .map(name => ({ name, code: INDIA_STATE_CODES[name] || 'IN' }))
  .sort((a, b) => a.name.localeCompare(b.name));

const normalize = (value: string) => value.trim().toLowerCase().replace(/[^a-z0-9]+/g, ' ');

export const findCanonicalDistrict = (state: string, district: string): string => {
  const wanted = normalize(district);
  return (INDIA_DISTRICTS_BY_STATE[state] || []).find(item => normalize(item) === wanted) || district;
};

export const getIndiaDistricts = (state: string): string[] => INDIA_DISTRICTS_BY_STATE[state] || [];

export const getIndiaAssemblies = (state: string, district: string): string[] => {
  const canonical = findCanonicalDistrict(state, district);
  const exact = INDIA_ASSEMBLIES_BY_DISTRICT[`${state}|${canonical}`];
  return exact?.length ? exact : (INDIA_ASSEMBLIES_BY_STATE[state] || []);
};

export const makeDistrictCode = (state: string, district: string): string => {
  const stateCode = INDIA_STATE_CODES[state] || 'IN';
  const compact = district.toUpperCase().replace(/[^A-Z0-9]/g, '');
  return `${stateCode}-${(compact.slice(0, 3) || 'DST').padEnd(3, 'X')}`;
};

